document.addEventListener('DOMContentLoaded', function () {
  const link = document.getElementById('outros-portais');
  const submenu = document.querySelector('.submenu-outros-portais');
  const header = document.querySelector('.acessibilidade_header');
  const seta = document.querySelector('#outros-portais svg');

  if (!link || !submenu || !header) return;

  function abrir() {
    submenu.style.display = 'block';
    link.setAttribute('aria-expanded', 'true');
    if (seta) seta.style.transform = 'rotate(180deg)';
  }

  function fechar() {
    submenu.style.display = 'none';
    link.setAttribute('aria-expanded', 'false');
    if (seta) seta.style.transform = 'rotate(0deg)';
  }

  link.addEventListener('click', (e) => {
    e.stopPropagation();
    e.preventDefault();
    submenu.style.display === 'block' ? fechar() : abrir();
  });

  document.addEventListener('click', (e) => {
    if (!header.contains(e.target)) fechar();
  });

  link.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      submenu.style.display === 'block' ? fechar() : abrir();
      if (submenu.style.display === 'block') {
        setTimeout(() => {
          const primeiro = submenu.querySelector('a, button');
          if (primeiro) primeiro.focus();
        }, 10);
      }
    }
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && submenu.style.display === 'block') {
      fechar();
      link.focus();
    }
  });

  submenu.addEventListener('keydown', (e) => {
    if (e.key === 'Tab' && submenu.style.display === 'block') {
      const focusaveis = Array.from(submenu.querySelectorAll('a, button, [tabindex="0"]'));

      if (focusaveis.length === 0) return;

      const primeiro = focusaveis[0];
      const ultimo = focusaveis[focusaveis.length - 1];

      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault();
        link.focus();
      }

      if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault();
        fechar();

        setTimeout(() => {
          const todosItensHeader = Array.from(header.querySelectorAll('a, button, [tabindex="0"]'));
          const indexAtual = todosItensHeader.indexOf(link);

          if (indexAtual !== -1 && todosItensHeader[indexAtual + 1]) {
            todosItensHeader[indexAtual + 1].focus();
          } else {
            if (todosItensHeader[0]) todosItensHeader[0].focus();
          }
        }, 10);
      }
    }
  });
});

