(function () {
    const SCRIPT_ID = 'sienna-accessibility-script';
    const GLOBAL_LISTENER_FLAG = '__siennaAltShortcutRegistered';
    const GLOBAL_CONTROLLER = '__siennaAccessibilityController';

    if (!window[GLOBAL_CONTROLLER]) {
        window[GLOBAL_CONTROLLER] = {
            lastFocused: null,
            resetting: false
        };
    }

    const state = window[GLOBAL_CONTROLLER];

    function loadSiennaScript() {
        if (document.getElementById(SCRIPT_ID)) {
            return;
        }

        const script = document.createElement('script');

        script.id = SCRIPT_ID;
        script.src = 'https://cdn.jsdelivr.net/npm/sienna-accessibility/dist/sienna-accessibility.umd.js';
        script.async = true;
			script.setAttribute('data-lang', 'pt');

        script.onload = function () {
            setTimeout(enhanceMenu, 300);
            setTimeout(enhanceMenu, 1000);
        };

        document.head.appendChild(script);
    }

    function patchSiennaSpeechLanguage() {
        if (!('speechSynthesis' in window) || window.__siennaSpeechLangPatched) {
            return;
        }

        window.__siennaSpeechLangPatched = true;

        var siennaTextMap = {
            'Sienna Screen Reader Enabled': 'Leitor de tela Sienna ativado',
            'Sienna Screen Reader Disabled': 'Leitor de tela Sienna desativado'
        };

        var originalSpeak = window.speechSynthesis.speak.bind(window.speechSynthesis);

        window.speechSynthesis.speak = function (utterance) {
            if (siennaTextMap[utterance.text]) {
                utterance.text = siennaTextMap[utterance.text];
            }

            utterance.lang = 'pt-BR';

            var voices = window.speechSynthesis.getVoices();
            var ptVoice = voices.find(function (voice) {
                return voice.lang && voice.lang.indexOf('pt') === 0;
            });

            if (ptVoice) {
                utterance.voice = ptVoice;
            }

            return originalSpeak(utterance);
        };
    }

    function getMenu() {
        return document.querySelector('.asw-menu');
    }

    function isVisible(element) {
        if (!element) return false;

        const style = window.getComputedStyle(element);

        return (
            style.display !== 'none' &&
            style.visibility !== 'hidden' &&
            style.opacity !== '0' &&
            element.getClientRects().length > 0
        );
    }

    function getOpenMenu() {
        const menu = getMenu();
        return menu && isVisible(menu) ? menu : null;
    }

    function getSiennaButton() {
        return (
            document.querySelector('.asw-menu-btn') ||
            document.querySelector('.sienna-accessibility-widget button')
        );
    }

    function getVisibleAccessibilityButton() {
        const buttons = document.querySelectorAll(
            '[data-sienna-custom-trigger], .accessibility-button'
        );

        for (let i = 0; i < buttons.length; i++) {
            if (isVisible(buttons[i])) {
                return buttons[i];
            }
        }

        return null;
    }

    function setAttr(element, name, value) {
        if (element && element.getAttribute(name) !== value) {
            element.setAttribute(name, value);
        }
    }

    function getFocusable(container) {
        const selector = [
            'a[href]',
            'button:not([disabled])',
            'input:not([disabled])',
            'select:not([disabled])',
            'textarea:not([disabled])',
            '[tabindex]:not([tabindex="-1"])',
            '[role="button"]:not([aria-disabled="true"])'
        ].join(',');

        return Array.prototype.filter.call(
            container.querySelectorAll(selector),
            isVisible
        );
    }

    function makeTextsFocusable(menu) {
        const elements = menu.querySelectorAll(
            '.asw-menu-reset, .asw-menu-title, .asw-card-title, .asw-label, .asw-amount'
        );

        Array.prototype.forEach.call(elements, function (element) {
            if (!element.hasAttribute('tabindex')) {
                element.setAttribute('tabindex', '0');
            }
        });
    }

    function addShortcutInfo(menu) {
        if (menu.querySelector('.sienna-shortcut-info')) {
            return;
        }

        const shortcut = document.createElement('div');

        shortcut.className = 'sienna-shortcut-info';
        shortcut.setAttribute('aria-label', 'Atalho do widget: ALT mais A');

        shortcut.innerHTML =
            '<span class="sienna-shortcut-info__label">Atalho do widget:</span>' +
            '<kbd class="sienna-shortcut-info__key">ALT</kbd>' +
            '<span class="sienna-shortcut-info__plus" aria-hidden="true">+</span>' +
            '<kbd class="sienna-shortcut-info__key">A</kbd>';

        const header = menu.querySelector('.asw-menu-header, .asw-header');
        const content = menu.querySelector('.asw-menu-content');

        if (header && header.parentNode === menu) {
            header.insertAdjacentElement('afterend', shortcut);
            return;
        }

        if (content && content.parentNode === menu) {
            menu.insertBefore(shortcut, content);
            return;
        }

        menu.insertBefore(shortcut, menu.firstChild);
    }

    function focusFirstInMenu() {
        const menu = getOpenMenu();

        if (!menu) {
            return;
        }

        enhanceMenu();

        const first =
            menu.querySelector('.asw-menu-title') ||
            getFocusable(menu)[0];

        if (first && first.focus) {
            first.focus({ preventScroll: true });
        }
    }

    function trapFocus(event, menu) {
        const focusable = getFocusable(menu);

        if (!focusable.length) {
            return;
        }

        const first = focusable[0];
        const last = focusable[focusable.length - 1];

        if (!menu.contains(document.activeElement)) {
            event.preventDefault();
            first.focus({ preventScroll: true });
            return;
        }

        if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last.focus({ preventScroll: true });
            return;
        }

        if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first.focus({ preventScroll: true });
        }
    }

    function patchKeyboardOnButtons(menu) {
        const selector = '.asw-plus, .asw-minus, .asw-btn, .asw-menu-close';

        Array.prototype.forEach.call(menu.querySelectorAll(selector), function (button) {
            if (button.getAttribute('data-kb-patched') === '1') {
                return;
            }

            button.setAttribute('data-kb-patched', '1');

            button.addEventListener('keydown', function (event) {
                if (event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault();
                    button.click();
                }
            });
        });
    }

    function restoreFontSize() {
        Array.prototype.forEach.call(
            document.querySelectorAll('[data-asw-org-font-size]'),
            function (element) {
                const originalSize = element.getAttribute('data-asw-org-font-size');

                if (originalSize) {
                    element.style.fontSize = originalSize + 'px';
                }

                element.removeAttribute('data-asw-org-font-size');
            }
        );

        Array.prototype.forEach.call(
            document.querySelectorAll('.asw-amount'),
            function (element) {
                element.textContent = '100%';
            }
        );
    }

    function patchResetButton(menu) {
        const buttons = menu.querySelectorAll(
            '.asw-menu-reset, .asw-menu-reset-footer-btn'
        );

        Array.prototype.forEach.call(buttons, function (button) {
            if (button.getAttribute('data-reset-patched') === '1') {
                return;
            }

            button.setAttribute('data-reset-patched', '1');

            button.addEventListener('click', function () {
                if (state.resetting) {
                    return;
                }

                state.resetting = true;

                if (button.classList.contains('asw-menu-reset-footer-btn')) {
                    const headerButton = menu.querySelector('.asw-menu-reset');

                    if (headerButton && headerButton !== button) {
                        try {
                            headerButton.click();
                        } catch (error) {}
                    }
                }

                setTimeout(restoreFontSize, 200);
                setTimeout(restoreFontSize, 600);

                setTimeout(function () {
                    state.resetting = false;
                }, 800);
            });

            button.addEventListener('keydown', function (event) {
                if (event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault();
                    button.click();
                }
            });
        });
    }

    function enhanceMenu() {
        const menu = getMenu();

        if (!menu) {
            return;
        }

        setAttr(menu, 'role', 'dialog');
        setAttr(menu, 'aria-modal', 'true');

        addShortcutInfo(menu);
        makeTextsFocusable(menu);
        patchKeyboardOnButtons(menu);
        patchResetButton(menu);
    }

    function openSienna() {
        state.lastFocused = document.activeElement;

        let attempts = 0;

        function tryOpen() {
            const siennaButton = getSiennaButton();

            if (siennaButton) {
                siennaButton.click();

                setTimeout(enhanceMenu, 150);
                setTimeout(focusFirstInMenu, 200);
                setTimeout(enhanceMenu, 500);

                return;
            }

            attempts++;

            if (attempts <= 10) {
                setTimeout(tryOpen, 150);
                return;
            }

            console.warn('[Sienna] Botão do widget ainda não encontrado.');
        }

        tryOpen();
    }

    function closeSienna() {
        const menu = getOpenMenu();

        if (!menu) {
            return;
        }

        const closeButton = menu.querySelector('.asw-menu-close');

        if (closeButton) {
            closeButton.click();
        } else {
            menu.style.display = 'none';
        }

        setTimeout(function () {
            const target = getVisibleAccessibilityButton() || state.lastFocused;

            if (target && target.focus) {
                target.focus({ preventScroll: true });
            }
        }, 100);
    }

    function toggleSienna() {
        if (getOpenMenu()) {
            closeSienna();
        } else {
            openSienna();
        }
    }

    function registerFragmentButtons() {
        if (typeof fragmentElement === 'undefined' || !fragmentElement) {
            return;
        }

        const buttons = fragmentElement.querySelectorAll(
            '.accessibility-button, [data-sienna-custom-trigger]'
        );

        Array.prototype.forEach.call(buttons, function (button) {
            if (button.getAttribute('data-sienna-fragment-patched') === '1') {
                return;
            }

            button.setAttribute('data-sienna-fragment-patched', '1');

            if (!button.hasAttribute('data-sienna-custom-trigger')) {
                button.setAttribute('data-sienna-custom-trigger', 'true');
            }

            button.addEventListener('click', function (event) {
                event.preventDefault();
                toggleSienna();
            });

            button.addEventListener('keydown', function (event) {
                if (event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault();
                    toggleSienna();
                }
            });
        });
    }

    function registerGlobalEvents() {
        if (window[GLOBAL_LISTENER_FLAG]) {
            return;
        }

        window[GLOBAL_LISTENER_FLAG] = true;

        document.addEventListener(
            'keydown',
            function (event) {
                const key = event.key ? event.key.toLowerCase() : '';

                const isAltA =
                    event.altKey &&
                    !event.ctrlKey &&
                    !event.shiftKey &&
                    !event.metaKey &&
                    (key === 'a' || event.code === 'KeyA');

                if (isAltA) {
                    const visibleButton = getVisibleAccessibilityButton();

                    if (!visibleButton) {
                        return;
                    }

                    event.preventDefault();
                    event.stopPropagation();

                    toggleSienna();
                    return;
                }

                const menu = getOpenMenu();

                if (!menu) {
                    return;
                }

                if (event.key === 'Escape') {
                    event.preventDefault();
                    event.stopPropagation();

                    closeSienna();
                    return;
                }

                if (event.key === 'Tab') {
                    trapFocus(event, menu);
                }
            },
            true
        );

        document.addEventListener('click', function (event) {
            const menu = getMenu();

            if (menu && menu.contains(event.target)) {
                setTimeout(enhanceMenu, 200);
            }
        });
    }

    patchSiennaSpeechLanguage();
    loadSiennaScript();
    registerFragmentButtons();
    registerGlobalEvents();

    setTimeout(enhanceMenu, 600);
    setTimeout(enhanceMenu, 1800);
})();
;

