(function() {
    const carouselWrapper = document.querySelector('.carousel-wrapper-exp');
    if (!carouselWrapper) return;

    const slides = document.querySelectorAll('.carousel-slide-exp');
    const prevBtn = document.querySelector('.carousel-btn-prev-exp');
    const nextBtn = document.querySelector('.carousel-btn-next-exp');

    if (slides.length === 0) return;

    let currentIndex = 0;
    let slideWidth = 341; 
    let gap = 20;
    let slidesPerView = 1;

    function calculateSlidesPerView() {
        const containerWidth = document.querySelector('.carousel-container-exp').offsetWidth;

        if (window.innerWidth >= 992) {
            slidesPerView = Math.floor(containerWidth / slideWidth + gap);
            slidesPerView = Math.max(1, Math.min(slidesPerView, 2));
        } else {
            slidesPerView = 1;
        }

        return slidesPerView;
    }

    function goToSlide(index) {
        const maxIndex = Math.max(0, slides.length - slidesPerView);
        currentIndex = Math.max(0, Math.min(index, maxIndex));

        const offset = currentIndex * (slideWidth + gap);
        carouselWrapper.style.transform = 'translateX(-' + offset +'px)';

        updateButtons();
    }

    function updateButtons() {
        if (!prevBtn || !nextBtn) return;

        if (currentIndex === 0) {
            prevBtn.style.opacity = '0.5';
            prevBtn.style.cursor = 'not-allowed';
        } else {
            prevBtn.style.opacity = '1';
            prevBtn.style.cursor = 'pointer';
        }

        if (currentIndex >= slides.length - slidesPerView) {
            nextBtn.style.opacity = '0.5';
            nextBtn.style.cursor = 'not-allowed';
        } else {
            nextBtn.style.opacity = '1';
            nextBtn.style.cursor = 'pointer';
        }
    }

    function nextSlide() {
        if (currentIndex < slides.length - slidesPerView) {
            goToSlide(currentIndex + 1);
        }
    }

    function prevSlide() {
        if (currentIndex > 0) {
            goToSlide(currentIndex - 1);
        }
    }

    if (prevBtn) {
        prevBtn.addEventListener('click', prevSlide);
    }

    if (nextBtn) {
        nextBtn.addEventListener('click', nextSlide);
    }

    let touchStartX = 0;
    let touchEndX = 0;

    carouselWrapper.addEventListener('touchstart', (e) => {
        touchStartX = e.changedTouches[0].screenX;
    }, { passive: true });

    carouselWrapper.addEventListener('touchend', (e) => {
        touchEndX = e.changedTouches[0].screenX;
        handleSwipe();
    }, { passive: true });

    function handleSwipe() {
        const swipeThreshold = 50;

        if (touchStartX - touchEndX > swipeThreshold) {
            nextSlide();
        }

        if (touchEndX - touchStartX > swipeThreshold) {
            prevSlide();
        }
    }

    document.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowLeft') {
            prevSlide();
        } else if (e.key === 'ArrowRight') {
            nextSlide();
        }
    });

    calculateSlidesPerView();
    updateButtons();
    fragmentElement.querySelector('#carousel-experiencia').style.display = 'block';

    window.addEventListener('resize', () => {
        calculateSlidesPerView();
        goToSlide(currentIndex);
    })
})();;

