.c-cotacao__radio-label {
  display: inline-block;
  vertical-align: middle;
  cursor: pointer;
}
.c-cotacao__radio-label {
  position: relative;
}
.c-cotacao__radio + .c-cotacao__radio-label:before {
  border-radius: 50%;
  margin-right: 0px;
