  background-position-x: right;
  appearance: none;
  -webkit-appearance: none;
  background-position-x: calc(100% - 10px);
}
.c-cotacao__select > select:disabled {
  background: url("data:image/svg+xml,%3Csvg width='16' height='9' viewBox='0 0 29 17' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1L13.5 15L27.5 1' stroke='%235B5B5F' stroke-width='2'/%3E%3C/svg%3E")
    no-repeat right #5b5b5f1a;
  background-position-x: right;
  appearance: none;
  -webkit-appearance: none;
  background-position-x: calc(100% - 10px);
}
.c-cotacao__btn {
  color: #ffffff;
  text-align: center;
  border-radius: 8px;
  width: 100%;
  height: 44px;
  font-family: "oxygen-bold";
  font-size: 16px;
  background-color: #ec6e0c;
