$(document).ready(function () {
  $('#tabpage1').click(function () {
    $('.tabInter1').css('display', 'block');
    $('.tabInter2').css('display', 'none');
    $('#tabpage1').addClass('campoGuiaStyle');
    $('#tabpage2').removeClass('campoGuiaStyle');

    if (odontoRadio.checked) {
      $('.tabInter3').css('display', 'none');
    } else {
      $('.tabInter3').css('display', 'block');
    }
  });
  $('#tabpage2').click(function () {
    $('.tabInter2').css('display', 'block');
    $('.tabInter1').css('display', 'none');
    $('#tabpage2').addClass('campoGuiaStyle');
    $('#tabpage1').removeClass('campoGuiaStyle');
  });

  $('#radio-option1').click(function () {
    $('.tabInter3').css('display', 'block');
    $('.tabInter4').css('display', 'none');
  });
  $('#radio-option2').click(function () {
    $('.tabInter3').css('display', 'none');
    $('.tabInter4').css('display', 'block');
  });
});;

