.ccg-banner {
	box-sizing: border-box;
	position: relative;
	display: flex;
	flex-direction: column;
	width: 100%;
	max-width: 480px;
	height: 484px;
	overflow: hidden;
	background: #F5F5F5;
	border: 1px solid #EFEEE7;
	border-radius: 3px;
	font-family: "oxygen-regular";
}

.ccg-banner *,
.ccg-banner *::before,
.ccg-banner *::after {
	box-sizing: border-box;
}

.ccg-banner.ccg-banner--two-ctas {
	height: 548px;
}

.ccg-banner.ccg-banner--no-bg {
	background: transparent;
	border-color: transparent;
}

.ccg-banner__media {
	position: relative;
	flex: 0 0 200px;
	width: 100%;
	height: 200px;
	overflow: hidden;
	background: #D9D9D9;
}

.ccg-banner__image {
	display: block;
	width: 100%;
	height: 100%;
	object-fit: cover;
	object-position: center;
}

.ccg-banner__content {
	position: relative;
	display: flex;
	flex: 1 1 auto;
	flex-direction: column;
	align-items: flex-start;
	justify-content: center;
	min-width: 0;
	width: 100%;
	padding: 20px 24px;
	gap: 16px;
}

.ccg-banner__text {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	width: 100%;
	gap: 8px;
}

.ccg-banner__title {
	display: -webkit-box;
	width: 100%;
	margin: 0;
	overflow: hidden;
	color: #000000;
	font-family: "oxygen-bold";
	font-size: 20px;
	font-style: normal;
	font-weight: 700;
	line-height: 1.8;
	-webkit-line-clamp: 2;
	-webkit-box-orient: vertical;
}

.ccg-banner__subtitle {
	display: -webkit-box;
	width: 100%;
	margin: 0;
	overflow: hidden;
	color: #5B5B5F;
	font-family: "oxygen-regular";
	font-size: 16px;
	font-style: normal;
	font-weight: 400;
	line-height: 1.625;
	-webkit-line-clamp: 3;
	-webkit-box-orient: vertical;
}

.ccg-banner__ctas {
	display: flex;
	flex-direction: column;
	align-items: stretch;
	width: 100%;
	gap: 12px;
}

.ccg-banner__cta {
	box-sizing: border-box;
	display: flex;
	overflow: hidden;
	align-items: center;
	justify-content: center;
	width: 100%;
	padding: 8px 16px;
	overflow: hidden;
	color: #FFFFFF;
	text-align: center;
	text-decoration: none;
	text-overflow: ellipsis;
	white-space: nowrap;
	background: #0435AC;
	border: 1px solid #0435AC;
	border-radius: 3px 3px 12px 3px;
	font-family: "oxygen-regular";
	font-size: 16px;
	font-weight: 700;
	line-height: 1.625;
	cursor: pointer;
	transition: background-color .2s ease, color .2s ease, opacity .2s ease;
}

.ccg-banner__cta:hover,
.ccg-banner__cta:focus {
	color: var(--color-trust, #0435AC);
    background: var(--color-default, #fff) 0% 0% no-repeat padding-box;
    border: 1px solid var(--color-trust, #0435AC);
	text-decoration: none;
}

.ccg-banner__cta--secondary {
	color: #0435AC;
	background: transparent;
}

.ccg-banner__cta--secondary:hover,
.ccg-banner__cta--secondary:focus {
	background: rgba(4, 53, 172, 0.08);
	color: #0435AC;
}

.ccg-banner__cta--overflow {
	letter-spacing: -0.1px;
}

/* ---------- Tablet: 768px – 991px ---------- */
@media (min-width: 768px) {
	.ccg-banner--image-right {
		flex-direction: row-reverse !important;
	}

	.ccg-banner {
		flex-direction: row;
		max-width: 100%;
		height: 241px;
	}

	.ccg-banner.ccg-banner--two-ctas {
		height: 241px;
	}

	.ccg-banner__media {
		flex: 0 0 270px;
		width: 270px;
		height: 100%;
	}

	.ccg-banner__content {
		padding: 24px 32px;
	}

	.ccg-banner__ctas {
		flex-direction: row;
		flex-wrap: wrap;
	}

	.ccg-banner__cta {
		width: auto;
		min-width: 160px;
		max-width: 233px;
	}
}

/* ---------- Desktop: a partir de 992px ---------- */
@media (min-width: 992px) {
	.ccg-banner {
		max-width: 100%;
	}
}

