.qualitotal-servicos .qualitotal-cards .slick-track{
	/*margin-right: 0px;*/
}
	.qualitotal-servicos .qualitotal-cards .slick-track	.qualitotal-card + .qualitotal-card{
	 margin-left:0px;
	} 
	@media (max-width:768px){
	.qualitotal-servicos .qualitotal-cards .slick-track	.qualitotal-card + .qualitotal-card{
	 margin-left:10px;
	}
	}
	@media (max-width:330px){
	.qualitotal-servicos .qualitotal-cards .slick-track	.qualitotal-card + .qualitotal-card{
	 margin-left:0px;
	}
	}

:root {
  --gap-slick: 12px;
}

.qualitotal-servicos .qualitotal-cards {
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 20px;
    margin: 40px 0;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-card {
    display: flex;
    flex-direction: column; 
    flex: 1 1 22%;
    min-width: 220px;
	  padding: 20px 4px;
    box-sizing: border-box;
    text-align: center;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-card h2 {
    font-size: 16px;
    margin: 0 0 15px 0;
    font-family: "oxygen-bold";
    color: #2D2D2D;
	  text-align:left;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-body {
    display: flex;
    align-items: center;
    gap: 15px;
    text-align: left;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-icon {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-shrink: 0;
    overflow: hidden;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-icon img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}
.qualitotal-servicos .qualitotal-cards .qualitotal-text p {
    font-size: 12px;
    margin: 0;
    color: #2D2D2D;
    font-family: "oxygen-regular";
}
/*custom slick*/
.qualitotal-servicos .qualitotal-cards .slick-list{
 display:flex;
 width:100%;
}
.qualitotal-servicos .qualitotal-cards .slick-track{
 display:flex;
	margin:0;
	width:100%;
}
.qualitotal-servicos .qualitotal-cards .slick-slide{
height:auto;
}
.qualitotal-servicos .arrow_prevQualitotal,
.qualitotal-servicos .arrow_nextQualitotal {
  display: none;
}
.qualitotal-servicos .qualitotal-cards .slick-dots li{
 width: 7px;
}
.qualitotal-servicos .qualitotal-cards .slick-dots li.slick-active button:before {
 background-color: var(--primary)!important;
	border-radius: 2px;
}
.qualitotal-servicos .qualitotal-cards li button:before{
 border: 1px solid var(--primary)!important;
	content:"";
	border-radius: 2px;
	width: 10px;
  height: 10px;
}
.qualitotal-servicos .qualitotal-cards .slick-dots li button:hover:before, .slick-dots li button:focus:before{
 color:initial;
}
.qualitotal-servicos .qualitotal-cards li.slick-active button:before{
 opacity:1;
}
.qualitotal-servicos .qualitotal-cards .slick-dots{
	display:flex;
}
/*Css para ajustar a espaçamento do dropzone*/
.page-editor__no-fragments-message {
    padding: 0!important;
}
@media (max-width: 768px) {
	.qualitotal-servicos .qualitotal-cards {
    display: flex;
    flex-wrap: nowrap;
}
	/*.qualitotal-servicos .qualitotal-cards .qualitotal-body {
  margin:auto;
}*/
	.qualitotal-servicos .qualitotal-cards .qualitotal-card{
 padding-left:0;
		padding-right:0;
}
}
@media (max-width: 330px){

	.qualitotal-servicos .qualitotal-cards .qualitotal-card{
	 min-width:auto;
	}
	.qualitotal-servicos .qualitotal-cards .qualitotal-card h2{
	font-size:14px;
	}
.qualitotal-servicos .qualitotal-cards .qualitotal-body {
    margin: initial;
}
	.qualitotal-servicos .qualitotal-cards .qualitotal-icon {
    width: 40px;
    height: 40px;
}
	.qualitotal-servicos .qualitotal-cards .qualitotal-text p {
    font-size: 10px;
}
}


